export const dynamicConfidenceCalibration = (taskPerformance, feedback) => {
  const adjustedConfidence = taskPerformance.map((task) => {
    const feedbackScore = feedback[task.id] || 0;
    return Math.max(0, Math.min(1, task.confidence + feedbackScore * 0.1));
  });
  return adjustedConfidence;
};